<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{teacherAPI}from'../../api/teacher';import type{Provider}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import{useToast}from'../../composables/useToast';const rows=ref<Provider[]>([]),query=ref(''),status=ref(''),drawer=ref(false),editing=ref<Provider|null>(null),credentialOpen=ref<Provider|null>(null),credential=ref(''),showCredential=ref(false),error=ref(''),routingModels=ref<string[]>([]),toast=useToast(),form=reactive({name:'',base_url:'',credential:'',status:'active' as'active'|'inactive'});const filtered=computed(()=>rows.value.filter(p=>(!query.value||`${p.name} ${p.base_url}`.toLowerCase().includes(query.value.toLowerCase()))&&(!status.value||p.status===status.value)));async function load(){try{rows.value=await teacherAPI.providers()}catch(e){error.value=msg(e)}}function open(p?:Provider){editing.value=p??null;Object.assign(form,{name:p?.name??'',base_url:p?.base_url??'',credential:'',status:p?.status??'active'});drawer.value=true}async function save(){try{if(editing.value)await teacherAPI.updateProvider(editing.value.id,{name:form.name,base_url:form.base_url,status:form.status});else await teacherAPI.createProvider(form);toast.success(editing.value?'供应商已更新':'供应商已创建');await load();if(!editing.value)drawer.value=false}catch(e){handle(e)}}async function replaceCredential(){if(!credentialOpen.value)return;try{await teacherAPI.updateProvider(credentialOpen.value.id,{credential:credential.value});toast.success('供应商凭据已替换');credentialOpen.value=null;credential.value=''}catch(e){handle(e)}}async function toggle(p:Provider){if(p.status==='active'&&!confirm('停用供应商可能影响模型路由，是否继续？'))return;try{await teacherAPI.updateProvider(p.id,{status:p.status==='active'?'inactive':'active'});await load()}catch(e){handle(e)}}function handle(e:unknown){if(e instanceof APIError&&e.code==='MODEL_ROUTING_REQUIRED'&&!Array.isArray(e.details)){routingModels.value=e.details?.model_ids??[]}else error.value=msg(e)}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'};onMounted(load);</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">TEACHER</p><h1>供应商管理</h1><p class="muted">凭据只写入不回显；普通编辑不会携带 credential。</p></div><button class="button primary" @click="open()">添加供应商</button></div><p v-if="error" class="error banner">{{error}}</p><section class="panel"><div class="grid two"><label>搜索<input v-model="query" placeholder="名称或 Base URL"/></label><label>状态<select v-model="status"><option value="">全部状态</option><option value="active">启用</option><option value="inactive">停用</option></select></label></div><article v-for="p in filtered" :key="p.id" class="list-row"><div><strong>{{p.name}}</strong><p class="muted">{{p.base_url}} · 凭据{{p.credential_configured?'已配置':'未配置'}}</p></div><div class="actions"><StatusBadge :status="p.status"/><button class="button ghost" @click="open(p)">编辑</button><button class="button secondary" @click="credentialOpen=p">替换凭据</button><button class="button" :class="p.status==='active'?'danger':'secondary'" @click="toggle(p)">{{p.status==='active'?'停用':'启用'}}</button></div></article></section><AppDialog :open="drawer" :title="editing?'编辑供应商':'创建供应商'" @update:open="drawer=$event"><form @submit.prevent="save"><label>名称<input v-model="form.name" required/></label><label>Base URL<input v-model="form.base_url" type="url" required/></label><label v-if="!editing">凭据<input v-model="form.credential" type="password" required/></label><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button class="button primary">保存</button></div></form></AppDialog><AppDialog :open="Boolean(credentialOpen)" title="替换供应商凭据" @update:open="credentialOpen=$event?credentialOpen:null"><label>新凭据<input v-model="credential" :type="showCredential?'text':'password'" required/></label><button class="button ghost wide" @pointerdown="showCredential=true" @pointerup="showCredential=false" @pointerleave="showCredential=false">按住临时显示</button><div class="actions"><button class="button primary" @click="replaceCredential">确认替换</button></div></AppDialog><AppDialog :open="Boolean(routingModels.length)" title="无法停用供应商" @update:open="routingModels=$event?routingModels:[]"><p>以下 ACTIVE 模型将失去最后一条可用路由：</p><div class="chip-list"><span v-for="id in routingModels" :key="id" class="chip">{{id}}</span></div></AppDialog></section></template>
